type Row = { id: string; [key: string]: string | number | boolean };
type Workspace = { entries: Row[]; customers: Row[]; suppliers: Row[]; products: Row[]; deals: Row[]; imports?: Row[]; roadmap: string[]; gates: string[]; defaultRate: number; profile?: Row };
type Snapshot = { revision: number; data: Workspace };
type Directory = 'customers' | 'suppliers' | 'products';
const tabs = ['New Sale','Accounting & FX','Xiamen Export Roadmap','Customers, Suppliers & Products','VAT Refund & Docs','Company Details','Invoices & Downloads','Import Purchases','Trade Reports','Dashboard'];
const steps = ['Supplier & purchase','Proforma invoice','Acceptance & invoice','Payment & packing','Customs & shipment','Settlement & close'];
const stepHints=['Record the supplier, products and actual purchase costs.','Choose the buyer, set selling prices and generate the proforma PDF. Mark it sent only after sending.','Record the buyer’s acceptance and prepare the commercial invoice.','Record actual customer payments and packing information. Generate a packing list.','Record genuine customs, freight and shipment references.','Reconcile the final payments, FX and tax treatment before closing.'];
const categories = { self_export: 'Self-operated export revenue 自营出口', entrusted_export: 'Entrusted export revenue 委托出口', vat_refund: 'VAT refund received 出口退税款', procurement: 'Procurement / special VAT fapiao 专票采购', customs_freight: 'Customs, port and freight 报关港杂海运', operating: 'Operating & admin 日常运营费用' };
